 mentionedJid: [m.sender],
 isForwarded: false,
 forwardingScore: 1
 }
 }
 },
 {
 userJid: m.sender,
 quoted: m
 }
)

// Tambahkan additionalNodes (opsional, untuk biz/interactive)
await conn.relayMessage(
 m.chat,
 msg.message,
 {
