 }
 ]
 }
 ]
 }
 ]
 }
)

await m.reply('✅ Tombol request contact berhasil dikirim!')

case 'requestcontact': {
 await alip.sendMessage(m.chat, { react: { text: '⏳', key: m.key } })
 try {
  const msg = generateWAMessageFromContent(
   m.chat,
   {
    interactiveMessage: {
     body: {
      text: "📱 *Minta Nomor WhatsApp*\n\nKlik tombol di bawah untuk mengirim nomor kamu."
     },
     footer: {
      text: "© Evernight AI"
     },
     nativeFlowMessage: {
      buttons: [
       {
        name: "request_contact_info",
        buttonParamsJson: "{}"
       }
      ],
      messageParamsJson: "{}"
     },
     contextInfo: {
      mentionedJid: [m.sender],
      isForwarded: false,
      forwardingScore: 1
     }
    }
   },
   {
    userJid: m.sender,
    quoted: m
   }
  )

  await alip.relayMessage(
   m.chat,
   msg.message,
   {
    additionalNodes: [
     {
      tag: "biz",
      attrs: {},
      content: [
       {
        tag: "interactive",
        attrs: { type: "native_flow", v: "1" },
        content: [
         {
          tag: "native_flow",
          attrs: { name: "request_contact_info" }
         }
        ]
       }
      ]
     }
    ]
   }
  )
  await alip.sendMessage(m.chat, { react: { text: '✅', key: m.key } })
  await Reply('✅ Tombol request contact berhasil dikirim!')
 } catch (e) {
  console.error(e)
  await alip.sendMessage(m.chat, { react: { text: '❌', key: m.key } })
  await Reply(global.mess.error)
 }
}
break
